/* Derivatives for referenced model: 'Blazer_Plant_Model' */
void Blazer_Plant_Model_Deriv(real_T *rty_Plantoutway_PCM_to_HSC_xdotref,
  B_Blazer_Plant_Model_c_T *localB, DW_Blazer_Plant_Model_f_T *localDW,
  X_Blazer_Plant_Model_n_T *localX, XDot_Blazer_Plant_Model_n_T *localXdot)
{
  /* Derivatives for TransferFcn: '<S83>/Sensor Dynamics' */
  localXdot->SensorDynamics_CSTATE = 0.0;
  localXdot->SensorDynamics_CSTATE += Blazer_Plant_Model_P.SensorDynamics_A *
    localX->SensorDynamics_CSTATE;
  localXdot->SensorDynamics_CSTATE += localB->ImpellerSpd;

  /* Derivatives for ModelReference: '<S82>/SiMappedEngine' incorporates:
   *  Constant: '<S10>/Constant6'
   *  Constant: '<S10>/Constant7'
   */
  SiMappedEngine_Deriv(&localB->ThrPosPctCmd, &localB->WgAreaPctCmd,
                       &localB->IntkCamPhaseCmd, &localB->ExhCamPhaseCmd,
                       &localB->SiEngineController_o8,
                       &localB->SiEngineController_o9,
                       &localB->SiEngineController_o10,
                       &localB->SiEngineController_o11,
                       &localB->SiEngineController_o12,
                       &localB->SiEngineController_o13,
                       &localB->SiEngineController_o14, &localB->TrqCmd,
                       &(localDW->SiMappedEngine_InstanceData.rtb),
                       &(localX->SiMappedEngine_CSTATE),
                       &(localXdot->SiMappedEngine_CSTATE));

  /* Derivatives for TransferFcn: '<S79>/Motor Coupling Dynamics' */
  localXdot->MotorCouplingDynamics_CSTATE = 0.0;
  localXdot->MotorCouplingDynamics_CSTATE +=
    Blazer_Plant_Model_P.MotorCouplingDynamics_A *
    localX->MotorCouplingDynamics_CSTATE;
  localXdot->MotorCouplingDynamics_CSTATE += localB->MotMapped_o1;

  /* Derivatives for Integrator: '<S97>/Integrator1' */
  localXdot->Integrator1_CSTATE = localB->Divide_b;

  /* Derivatives for ModelReference: '<S76>/DrivetrainHevP4' incorporates:
   *  Constant: '<S10>/Constant2'
   *  Constant: '<S10>/Constant3'
   */
  DrivetrainHevP4_Deriv(&(localDW->DrivetrainHevP4_InstanceData.rtb),
                        &(localDW->DrivetrainHevP4_InstanceData.rtdw),
                        &(localX->DrivetrainHevP4_CSTATE),
                        &(localXdot->DrivetrainHevP4_CSTATE));

  /* Derivatives for TransferFcn: '<S79>/Battery Discharge Dynamics' */
  localXdot->BatteryDischargeDynamics_CSTATE = 0.0;
  localXdot->BatteryDischargeDynamics_CSTATE +=
    Blazer_Plant_Model_P.BatteryDischargeDynamics_A *
    localX->BatteryDischargeDynamics_CSTATE;
  localXdot->BatteryDischargeDynamics_CSTATE += localB->BattCrnt;

  /* Derivatives for ModelReference: '<S85>/Battery' */
  BattHev_Deriv(&(localDW->Battery_InstanceData.rtb), &(localX->Battery_CSTATE),
                &(localXdot->Battery_CSTATE));

  /* Derivatives for Integrator: '<S114>/Integrator' */
  localXdot->Integrator_CSTATE = localB->Sqrt;

  /* Derivatives for Integrator: '<S114>/Integrator1' */
  localXdot->Integrator1_CSTATE_n = localB->TotFuel;

  /* Derivatives for Integrator: '<S113>/Integrator' */
  localXdot->Integrator_CSTATE_a = *rty_Plantoutway_PCM_to_HSC_xdotref;

  /* Derivatives for Integrator: '<S113>/Integrator3' */
  localXdot->Integrator3_CSTATE = localB->TPNOx;

  /* Derivatives for Integrator: '<S113>/Integrator4' */
  localXdot->Integrator4_CSTATE = localB->SiMappedEngine_o34;

  /* Derivatives for Integrator: '<S113>/Integrator2' */
  localXdot->Integrator2_CSTATE = localB->TPCO;

  /* Derivatives for Integrator: '<S113>/Integrator1' */
  localXdot->Integrator1_CSTATE_m = localB->TPHC;

  /* Derivatives for TransferFcn: '<S79>/Coupling Dynamics1' */
  localXdot->CouplingDynamics1_CSTATE = 0.0;
  localXdot->CouplingDynamics1_CSTATE +=
    Blazer_Plant_Model_P.CouplingDynamics1_A * localX->CouplingDynamics1_CSTATE;
  localXdot->CouplingDynamics1_CSTATE += localB->StartTrq_e;

  /* Derivatives for ModelReference: '<S86>/MotMapped' */
  MotMapped_Deriv(&(localDW->MotMapped_InstanceData.rtb),
                  &(localXdot->MotMapped_CSTATE));

  /* Derivatives for ModelReference: '<S79>/Low Voltage Starting System' */
  StarterSystemP2_Deriv(&(localDW->LowVoltageStartingSystem_InstanceData.rtb),
                        &(localX->LowVoltageStartingSystem_CSTATE),
                        &(localXdot->LowVoltageStartingSystem_CSTATE));

  /* Derivatives for TransferFcn: '<S83>/Electronic Throttle Actuator Dynamics' */
  localXdot->ElectronicThrottleActuatorDynamics_CSTATE = 0.0;
  localXdot->ElectronicThrottleActuatorDynamics_CSTATE +=
    Blazer_Plant_Model_P.ElectronicThrottleActuatorDynamics_A *
    localX->ElectronicThrottleActuatorDynamics_CSTATE;
  localXdot->ElectronicThrottleActuatorDynamics_CSTATE += localB->TrqCmd;

  /* Derivatives for Integrator: '<S108>/Integrator2' */
  localXdot->Integrator2_CSTATE_l = localB->Product_c;
}

/* Model initialize function */
